import sys

def pow_opt(x, n):
    if n == 0:
        return 1.0
    N = n
    if N == -2**31:
        x, N = 1 / x, 2**31
    else:
        N = abs(N)
    res = 1.0
    cur = x
    while N > 0:
        if N & 1:
            res *= cur
        cur *= cur
        N >>= 1
    if n < 0:
        res = 1 / res
    return res

if __name__ == '__main__':
    data = sys.stdin.read().split()
    x = float(data[0]); n = int(data[1])
    print(f'{pow_opt(x, n):.5f}')

import sys

def pow_best(x, n):
    if n == 0:
        return 1.0
    if n < 0:
        x, n = 1.0 / x, -n
    def fast(b, e):
        if e == 0: return 1.0
        if e == 1: return b
        half = fast(b, e // 2)
        return half * half if e % 2 == 0 else half * half * b
    return fast(x, n)

if __name__ == '__main__':
    data = sys.stdin.read().split()
    x = float(data[0]); n = int(data[1])
    print(f'{pow_best(x, n):.5f}')
